function reconcileWorkbook(current){
 const payload=structuredClone(current),report={id:WORKBOOK.id,source:WORKBOOK.file,records:WORKBOOK.count,added:0,linked:0,archived:0,preserved:0,enriched:0};
 payload.workbookImports=payload.workbookImports||[];
 if(payload.workbookImports.includes(WORKBOOK.id))return {payload,report,alreadyApplied:true};
 const oldCampaigns=new Map(PREVIOUS_BOT.map(p=>[Number(p.fila),p]));
 const newTitles=new Map(WORKBOOK.campaigns.map(p=>[normalizeTitle(p.titulo),p]));
 // Earlier source row numbers refer to another spreadsheet version. Remap by title.
 for(const [key,row]of Object.entries(payload.productoDefaults||{})){
  const original=oldCampaigns.get(Number(row)),replacement=original&&newTitles.get(normalizeTitle(original.titulo));
  if(replacement)payload.productoDefaults[key]=replacement.fila;else delete payload.productoDefaults[key];
 }
 for(const o of payload.offers){
  const seed=ORIGINAL_EXAMPLES.find(x=>x.id===o.id&&x.id!=='BOT-MDE-005');
  if(seed&&exampleUnedited(o,seed)){o.archived=true;o.archiveReason='Ejemplo inicial sustituido por la importación íntegra del Excel.';report.archived++;}
 }
 const claimed=new Set();
 for(const source of WORKBOOK.offers){
  const existing=payload.offers.find(o=>!claimed.has(o.id)&&!o.archived&&o.source!=='CAZADOR_PILOTO'&&(o.workbookKey===source.workbookKey||(normalizeTitle(o.title)===normalizeTitle(source.title)&&o.id!==source.id)));
  if(existing){
   // Preserve all editable values, including messages, prices and approval state.
   existing.workbookKey=source.workbookKey;existing.workbookSourceText=source.workbookSourceText;existing.workbookType=source.workbookType;existing.workbookFile=WORKBOOK.file;
   existing.sourceCampaignRow=source.sourceCampaignRow;
   const prior=PREVIOUS_BOT.find(p=>normalizeTitle(p.titulo)===normalizeTitle(existing.title));
   if(prior&&existing.status==='BORRADOR'&&!existing.periods.length&&!existing.variants.length&&existing.sourceText===prior.contenido&&existing.commercialMessage===prior.contenido){
    existing.periods=structuredClone(source.periods);existing.variants=structuredClone(source.variants);
    existing.sourceText=source.sourceText;existing.commercialMessage=source.commercialMessage;existing.messageMode='ORIGINAL_EXCEL';existing.sourceFile=source.sourceFile;existing.priceConfirmed=false;existing.availabilityConfirmed=false;report.enriched++;
   }
   claimed.add(existing.id);report.linked++;report.preserved++;
  }else if(!payload.offers.some(o=>o.id===source.id)){
   payload.offers.push(structuredClone(source));claimed.add(source.id);report.added++;
  }else{throw Error('Conflicto de identificador en la importación del Excel.');}
 }
 payload.workbookImports.push(WORKBOOK.id);payload.workbookImportReport=report;
 return {payload,report,alreadyApplied:false};
}

const same=(a,b)=>JSON.stringify(a)===JSON.stringify(b);
function mergeImportedEntities(current,baseline,next){
 if(same(current,baseline))return structuredClone(next);
 const oldMap=new Map((baseline||[]).map(x=>[x.id,x])),newMap=new Map((next||[]).map(x=>[x.id,x]));
 const out=[];
 for(const entity of current||[]){const before=oldMap.get(entity.id),after=newMap.get(entity.id);
  if(before&&!after&&same(entity,before))continue;
  const merged=structuredClone(entity);
  if(before&&after)for(const key of Object.keys(after))if(same(entity[key],before[key]))merged[key]=structuredClone(after[key]);
  out.push(merged);
 }
 for(const entity of next||[])if(!oldMap.has(entity.id)&&!out.some(x=>x.id===entity.id))out.push(structuredClone(entity));
 return out;
}
function repairWorkbook(current){
 const payload=structuredClone(current),report={id:STRUCTURED.id,updated:0,preservedFields:0,records:STRUCTURED.count};
 payload.workbookImports=payload.workbookImports||[];
 if(payload.workbookImports.includes(STRUCTURED.id))return {payload,report,alreadyApplied:true};
 for(const source of STRUCTURED.offers){
  const offer=payload.offers.find(o=>o.workbookKey===source.workbookKey&&!o.archived);if(!offer)continue;
  const before=WORKBOOK.offers.find(o=>o.workbookKey===source.workbookKey);let changed=false;
  for(const key of ['includes','excludes','conditions','charges','promos','itinerary']){
   if(same(offer[key],before[key])||!offer[key]?.length){if(!same(offer[key],source[key])){offer[key]=structuredClone(source[key]);changed=true;}}
   else if(!same(offer[key],source[key]))report.preservedFields++;
  }
  for(const key of ['periods','variants']){
   const merged=mergeImportedEntities(offer[key],before[key],source[key]);
   if(!same(merged,offer[key])){offer[key]=merged;changed=true;}
  }
  for(const key of ['dest','destName','kind','notes','messageMode','description']){
   if(same(offer[key],before[key])||!offer[key]){if(!same(offer[key],source[key])){offer[key]=source[key];changed=true;}}
   else if(!same(offer[key],source[key]))report.preservedFields++;
  }
  offer.importedCommercialMessage=before.commercialMessage;
  if(changed){if(offer.status==='PUBLICADA_DEMO')offer.status='EN_REVISION';offer.priceConfirmed=false;offer.availabilityConfirmed=false;offer.updatedAt='2026-11-12';report.updated++;}
 }
 payload.workbookImports.push(STRUCTURED.id);payload.workbookStructureReport=report;
 return {payload,report,alreadyApplied:false};
}
