function commercialOfferSnapshot(o){const {internalPaymentPlan,internalAssembly,updatedAt,...commercial}=o;return JSON.stringify(commercial);}
const json=(data,status=200)=>Response.json(data,{status,headers:{'Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}});
