function summary(prev,next){const before=new Map((prev?.offers||[]).map(o=>[o.id,JSON.stringify(o)]));const after=new Map(next.offers.map(o=>[o.id,JSON.stringify(o)]));let added=0,edited=0,removed=0;for(const [id,value]of after){if(!before.has(id))added++;else if(before.get(id)!==value)edited++;}for(const id of before.keys())if(!after.has(id))removed++;return `${added} nuevas · ${edited} modificadas · ${removed} eliminadas${JSON.stringify(prev?.productoDefaults)!==JSON.stringify(next.productoDefaults)?' · prioridades actualizadas':''}`;}
async function readState(db){const row=await db.prepare('SELECT revision,payload,updated_at FROM workspace_state WHERE id=1').first();return row?{revision:row.revision,payload:JSON.parse(row.payload),updatedAt:row.updated_at}:{revision:0,payload:null};}
